{
    if (n == 0 || n == 1)
        return true;
    else
        return isFibonacci(n - 1) || isFibonacci(n - 2);
}

int fib(int n)
{
    if (n == 0)
        return 0;
    else if (n == 1)
        return 1;
    else if (isFibonacci(n - 1))
        return fib(n - 1);
    else if (isFibonacci(n - 2))
        return fib(n - 2) + fib(n - 1);
